// One readable sentence, not a stack trace.
//
// An alert that takes effort to read gets muted, and a muted alert is worse than
// no alert, because it looks like coverage. So this answers the three questions
// someone actually has at 7am: what broke, where, and is it still broken.

const out = [];

for (const item of $input.all()) {
  const e = item.json;
  const wf = e.workflow?.name ?? 'unknown workflow';
  const node = e.execution?.lastNodeExecuted ?? 'unknown node';
  const msg = e.execution?.error?.message ?? e.trigger?.error?.message ?? 'no message';
  const url = e.execution?.url ?? '';
  const when = e.execution?.error?.timestamp ?? new Date().toISOString();

  // Anything with a token or key in it must not be forwarded into a Slack channel
  // that is usually wider than the people who should see credentials.
  const safe = String(msg)
    .replace(/(Bearer\s+)[A-Za-z0-9._\-]+/gi, '$1[redacted]')
    .replace(/((?:api[_-]?key|token|secret|password)["'\s:=]+)[^\s"',}]+/gi, '$1[redacted]')
    .slice(0, 800);

  out.push({
    json: {
      text: [
        `:rotating_light: *${wf}* failed`,
        `Stopped at: *${node}*`,
        `Error: ${safe}`,
        url ? `<${url}|Open the failed run>` : `(self-hosted: check Executions)`,
        `Time: ${when}`,
      ].join('\n'),
      workflow: wf,
      node,
      error: safe,
    },
  });
}

return out;
